import re,json,hashlib,pathlib
d='products/distribution/catalogue-offer-visibility/'
out={}
for k in ['url','title','intent']:
  b=pathlib.Path(d+'raw-bing-'+k+'.html').read_bytes(); t=b.decode('utf-8','replace')
  links=re.findall(r'<li class="b_algo".*?<a[^>]*href="(https?://[^"]+)"',t,re.S)
  cites=re.findall(r'<cite[^>]*>(.*?)</cite>',t,re.S)
  out[k]={'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'b_algo_count':t.count('class="b_algo"'),'result_links':links[:10],'cites':[re.sub('<[^>]+>','',c) for c in cites[:10]],'host_mentions':t.count('global-land.workers.dev'),'globalland_mentions':t.lower().count('globalland'),'captcha_markers':[m for m in ['captcha','challenge','verify you are','unusual traffic'] if m in t.lower()],'no_results_marker':('b_no' in t) or ('There are no results' in t),'title':(re.search(r'<title>(.*?)</title>',t,re.S) or [None,None])[1]}
print(json.dumps(out,indent=1)[:6000])
